require "rails_helper"

RSpec.describe TimekeepingLocalOwnerSpecHelpers do
  # The foreign-id example needs one user who holds the same role in both companies,
  # so the foreign entry differs from the caller only in company.
  it "timekeeping_member employs a user with the role and can give one user the same role in two companies" do
    company_a = create(:company)
    company_b = create(:company)

    owner = timekeeping_member(company_a, "owner")
    same_owner = timekeeping_member(company_b, "owner", user: owner)

    expect(same_owner.id).to eq(owner.id)
    expect(Employment.where(user_id: owner.id).pluck(:company_id)).to contain_exactly(company_a.id, company_b.id)
    expect(owner.reload.has_role?("owner", company_a)).to be(true)
    expect(owner.has_role?("owner", company_b)).to be(true)
    expect(owner.has_role?("employee", company_a)).to be(false)
  end
end

