require "rails_helper"

RSpec.describe "TimekeepingLocalOwnerSpecHelpers" do
  # "Move the shared count, row_counts and ownership setup into one spec/support helper."
  # A refused write that still leaves a row in any one of these tables must show up as a
  # changed count; a default table list that drops one would let that leak pass silently.
  it "shared row counts see a stray row in every table a write touches, so no refusal check is narrower than its widest copy" do
    prepare_local_ownership!
    company = create(:company)
    user = timekeeping_member(company, "employee")
    project = create(:project, client: create(:client, company:))
    before = timekeeping_row_counts

    expect(before.keys).to match_array(%w[entries entry_audits idempotency_records entry_outbox_items])

    outcome = Timekeeping::LocalOwner.call(
      operation: :create, company_id: company.id, generation: TimekeepingOwnership.current.generation.to_s,
      actor: Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "employee"),
      params: {
        "idempotency_key" => SecureRandom.uuid,
        "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 30.0,
                    "note" => "counted", "source" => "manual", "source_metadata" => {} }
      }
    )

    expect(outcome.status).to eq(201)
    after = timekeeping_row_counts
    before.each_key { |table| expect(after[table]).to eq(before[table] + 1), "#{table} write was not counted" }
  end
end

# frozen_string_literal: true
require "rails_helper"

RSpec.describe "TimekeepingLocalOwnerSpecHelpers" do
  # "Move the shared count, row_counts and ownership setup into one spec/support helper."
  # Examples run in any order, so the shared setup must undo a handoff step an earlier
  # arrangement left set; otherwise every write is refused as stale_generation.
  it "prepare local ownership clears a handoff step left set, so a write at the current generation is accepted again" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: "close_admission")
    company = create(:company)
    user = timekeeping_member(company, "employee")
    project = create(:project, client: create(:client, company:))
    write = lambda do |key|
      Timekeeping::LocalOwner.call(
        operation: :create, company_id: company.id, generation: TimekeepingOwnership.current.generation.to_s,
        actor: Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "employee"),
        params: {
          "idempotency_key" => key,
          "body" => { "project_id" => project.id, "work_date" => Date.current.iso8601, "duration" => 15.0,
                      "note" => "", "source" => "manual", "source_metadata" => {} }
        }
      )
    end

    refused = write.call("during-handoff")
    expect(refused.status).to eq(409)
    expect(refused.body.with_indifferent_access[:reason]).to eq("stale_generation")

    ownership = prepare_local_ownership!

    expect(ownership).to eq(TimekeepingOwnership.current)
    expect(ownership.reload.handoff_step).to be_nil
    expect(ownership.monolith_store).to eq("prepared")
    expect(write.call("after-prepare").status).to eq(201)
  end
end

# frozen_string_literal: true
require "rails_helper"

RSpec.describe "TimekeepingLocalOwnerSpecHelpers" do
  # "Each write-path change means editing three to five copies of each case: the foreign-id case appears in five files, credential_in_body in four, and the stale retry, entry_written rollback and locked-from-reservations cases in three each."
  # The merged foreign-id case uses one user with the same role in both companies, so the
  # entry differs from the caller only in company: only the company check can refuse it.
  it "a member of two companies updating one company's entry from the other answers exactly like a missing id" do
    prepare_local_ownership!
    company_a = create(:company)
    company_b = create(:company)
    user = timekeeping_member(company_a, "owner")
    expect(timekeeping_member(company_b, "owner", user:)).to eq(user)
    expect(user.has_role?(:owner, company_a)).to be(true)
    expect(user.has_role?(:owner, company_b)).to be(true)
    project_a = create(:project, client: create(:client, company: company_a))
    entry_a = Timekeeping::LocalEntry.create!(
      company_id: company_a.id, user_id: user.id, project_id: project_a.id, work_date: Date.current,
      duration: 60.0, note: "company a", bill_status: TimesheetEntry.bill_statuses.keys.find { |s| s != "billed" }
    )
    attributes_before = entry_a.reload.attributes
    counts_before = timekeeping_row_counts
    expect(counts_before["entries"]).to eq(1)
    update_from_b = lambda do |entry_id, key|
      Timekeeping::LocalOwner.call(
        operation: :update, company_id: company_b.id, generation: TimekeepingOwnership.current.generation.to_s,
        actor: Timekeeping::LocalOwner::Actor.user(user_id: user.id, role: "owner"),
        params: { "idempotency_key" => key, "entry_id" => entry_id,
                  "body" => { "note" => "taken over", "company_id" => company_a.id } }
      )
    end

    foreign = update_from_b.call(entry_a.id, "two-company-foreign")
    missing = update_from_b.call(entry_a.id + 1_000_000, "two-company-missing")

    expect(foreign.status).to eq(404)
    expect(foreign.status).to eq(missing.status)
    expect(foreign.body).to eq(missing.body)
    expect(entry_a.reload.attributes).to eq(attributes_before)
    expect(timekeeping_row_counts).to eq(counts_before)
  end
end
